CREATE TABLE IF NOT EXISTS tenants(id TEXT PRIMARY KEY,name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS invoices(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),customer TEXT NOT NULL,amount_cents INTEGER NOT NULL,status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY,at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,agent_id TEXT NOT NULL,user_id TEXT NOT NULL,tool TEXT NOT NULL,disposition TEXT NOT NULL,reason TEXT NOT NULL,resource_id TEXT);
CREATE TABLE IF NOT EXISTS approvals(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,invoice_id TEXT NOT NULL,amount_cents INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING',fingerprint TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS payments(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,invoice_id TEXT NOT NULL,amount_cents INTEGER NOT NULL,status TEXT NOT NULL);
